"""Bot navigation: waypoint steering around blockers, stuck recovery, open-point helpers.

Routing is a greedy corner detour: when the straight segment to the next waypoint is blocked,
the bot heads for the corner (offset CORNER_OFFSET metres) of the first blocker on that segment
that is visible and shortest via, then re-checks the segment from there. Development map
blockers are disjoint convex boxes with walkable gaps, so corner hopping gets around them; the
stuck detector covers the rest.

Navigation only sets intents (`move_x`, `move_y`, `sprinting`); movement.py moves the bot.
"""

import math
import random

from solo_engine.spatial import BlockerIndex, blocker_index
from solo_engine.geometry import distance, inside_any, normalize
from solo_engine.model import BotBrain, MapDefinition, Participant, Rect

ARRIVE_RADIUS = 1.0  # metres from a waypoint that counts as reaching it
CORNER_OFFSET = 1.5  # metres a detour corner keeps from the blocker in both axes
ROUTE_DEPTH = 4  # corner hops planned ahead; follow() re-plans from each corner when needed
STUCK_WINDOW = 2.0  # seconds
STUCK_DISTANCE = 0.5  # metres moved within STUCK_WINDOW below which the bot counts as stuck
SIDESTEP = (3.0, 6.0)  # metres
MAX_POPS_PER_TICK = 6

MOVING = "moving"
ARRIVED = "arrived"
STUCK = "stuck"


def stop(p: Participant) -> None:
    p.move_x = 0.0
    p.move_y = 0.0
    p.sprinting = False


def is_open(game_map: MapDefinition, x: float, y: float) -> bool:
    """Same answer as maps.is_open_point, using the cached blocker index."""
    if not (0.0 <= x <= game_map.size and 0.0 <= y <= game_map.size):
        return False
    return not blocker_index(game_map).contains(x, y) and not inside_any(x, y, game_map.water)


def open_point_near(
    game_map: MapDefinition, x: float, y: float, rng: random.Random, radius: float = 6.0, tries: int = 16
) -> tuple[float, float] | None:
    """(x, y) clamped into the map if it is open, else a random open point within `radius`."""
    size = game_map.size
    x, y = min(max(x, 0.0), size), min(max(y, 0.0), size)
    if is_open(game_map, x, y):
        return x, y
    for _ in range(tries):
        angle = rng.uniform(0.0, math.tau)
        r = radius * math.sqrt(rng.random())
        px, py = x + math.cos(angle) * r, y + math.sin(angle) * r
        if is_open(game_map, px, py):
            return px, py
    return None


def _corners(rect: Rect) -> tuple[tuple[float, float], ...]:
    o = CORNER_OFFSET
    return (
        (rect.min_x - o, rect.min_y - o),
        (rect.max_x + o, rect.min_y - o),
        (rect.max_x + o, rect.max_y + o),
        (rect.min_x - o, rect.max_y + o),
    )


def route(
    index: BlockerIndex,
    game_map: MapDefinition,
    sx: float,
    sy: float,
    gx: float,
    gy: float,
    depth: int = ROUTE_DEPTH,
) -> list[tuple[float, float]]:
    """Waypoints from (sx, sy) to (gx, gy); the last entry is always the goal."""
    goal = (gx, gy)
    if depth <= 0 or index.los(sx, sy, gx, gy):
        return [goal]
    rect = index.first_hit(sx, sy, gx, gy)
    if rect is None:
        return [goal]
    size = game_map.size
    best_visible: tuple[float, float] | None = None
    best_visible_score = math.inf
    best_any: tuple[float, float] | None = None
    best_any_score = math.inf
    for cx, cy in _corners(rect):
        if not (0.0 <= cx <= size and 0.0 <= cy <= size):
            continue
        if distance(sx, sy, cx, cy) < ARRIVE_RADIUS or index.contains(cx, cy):
            continue
        score = distance(sx, sy, cx, cy) + distance(cx, cy, gx, gy)
        if score < best_any_score:
            best_any, best_any_score = (cx, cy), score
        if score < best_visible_score and index.los(sx, sy, cx, cy):
            best_visible, best_visible_score = (cx, cy), score
    if best_visible is not None:
        return [best_visible] + route(index, game_map, best_visible[0], best_visible[1], gx, gy, depth - 1)
    if best_any is not None:
        return route(index, game_map, sx, sy, best_any[0], best_any[1], depth - 1) + [goal]
    return [goal]


def set_destination(
    brain: BotBrain,
    p: Participant,
    index: BlockerIndex,
    game_map: MapDefinition,
    dest: tuple[float, float],
    now: float,
    straight: bool = False,
) -> None:
    """Plan a path to `dest` and reset stuck tracking."""
    brain.destination = dest
    brain.path = [dest] if straight else route(index, game_map, p.x, p.y, dest[0], dest[1])
    brain.stuck_since = now
    brain.last_position = (p.x, p.y)


def clear(brain: BotBrain, p: Participant, now: float) -> None:
    brain.destination = None
    brain.path.clear()
    brain.stuck_since = now
    brain.last_position = (p.x, p.y)
    stop(p)


def follow(
    p: Participant,
    brain: BotBrain,
    index: BlockerIndex,
    game_map: MapDefinition,
    rng: random.Random,
    now: float,
    detect_stuck: bool = True,
) -> str:
    """Steer along brain.path for this tick. Returns MOVING, ARRIVED (path done) or STUCK."""
    path = brain.path
    pops = 0
    while path and pops < MAX_POPS_PER_TICK:
        wx, wy = path[0]
        if (p.x - wx) ** 2 + (p.y - wy) ** 2 > ARRIVE_RADIUS * ARRIVE_RADIUS:
            break
        path.pop(0)
        pops += 1
        if path:
            nx, ny = path[0]
            if not index.los(p.x, p.y, nx, ny):
                path[0:1] = route(index, game_map, p.x, p.y, nx, ny, depth=2)
    if not path:
        stop(p)
        brain.stuck_since = now
        brain.last_position = (p.x, p.y)
        return ARRIVED
    wx, wy = path[0]
    dx, dy = normalize(wx - p.x, wy - p.y)
    p.move_x, p.move_y = dx, dy
    if not detect_stuck:
        return MOVING
    if brain.stuck_since < 0:
        brain.stuck_since = now
        brain.last_position = (p.x, p.y)
        return MOVING
    if now - brain.stuck_since < STUCK_WINDOW:
        return MOVING
    lx, ly = brain.last_position
    moved = distance(lx, ly, p.x, p.y)
    brain.stuck_since = now
    brain.last_position = (p.x, p.y)
    if moved >= STUCK_DISTANCE:
        return MOVING
    side = 1.0 if rng.random() < 0.5 else -1.0
    reach = rng.uniform(*SIDESTEP)
    sx, sy = p.x - dy * side * reach - dx * 1.0, p.y + dx * side * reach - dy * 1.0
    if is_open(game_map, sx, sy):
        path.insert(0, (sx, sy))
    return STUCK


def cover_point(
    index: BlockerIndex,
    game_map: MapDefinition,
    p: Participant,
    threat_x: float,
    threat_y: float,
    radius: float = 25.0,
) -> tuple[float, float] | None:
    """Nearest open point behind a nearby blocker where the threat has no line of sight."""
    best: tuple[float, float] | None = None
    best_d = math.inf
    for rect in index.near(p.x, p.y, radius):
        cx, cy = (rect.min_x + rect.max_x) / 2.0, (rect.min_y + rect.max_y) / 2.0
        dx, dy = normalize(cx - threat_x, cy - threat_y)
        if dx == 0.0 and dy == 0.0:
            continue
        hx, hy = (rect.max_x - rect.min_x) / 2.0, (rect.max_y - rect.min_y) / 2.0
        tx = hx / abs(dx) if abs(dx) > 1e-9 else math.inf
        ty = hy / abs(dy) if abs(dy) > 1e-9 else math.inf
        t = min(tx, ty) + 1.2
        px, py = cx + dx * t, cy + dy * t
        d = distance(p.x, p.y, px, py)
        if d > radius or d >= best_d:
            continue
        if not is_open(game_map, px, py) or index.contains(px, py):
            continue
        if index.los(threat_x, threat_y, px, py):
            continue
        best, best_d = (px, py), d
    return best
